import { FaHome, FaUserPlus, FaVoteYea, FaChartBar, FaSignOutAlt } from "react-icons/fa";
import { useNavigate } from "react-router-dom";

function Sidebar() {
  const navigate = useNavigate();

  const logout = () => {
    localStorage.clear();
    navigate("/");
  };

  return (
    <div className="sidebar">
      <h3 className="logo">🗳 Voting</h3>

      <ul>
        <li onClick={() => navigate("/dashboard")}>
          <FaHome /> Dashboard
        </li>

        <li onClick={() => navigate("/add-election")}>
          <FaUserPlus /> Add Election
        </li>

        <li onClick={() => navigate("/add-candidate")}>
          <FaUserPlus /> Add Candidate
        </li>

        <li onClick={() => navigate("/vote")}>
          <FaVoteYea /> Vote
        </li>

        <li onClick={() => navigate("/result")}>
          <FaChartBar /> Results
        </li>
      </ul>

      <button className="logout-btn" onClick={logout}>
        <FaSignOutAlt /> Logout
      </button>
    </div>
  );
}

export default Sidebar;
